I’m writing the spending utility in Python, with an input path argument.
```bash
cat > tool.py <<'PY'
#!/usr/bin/env python3
"""Print spending totals grouped by category."""
import argparse
from collections import defaultdict
from decimal import Decimal, InvalidOperation
from pathlib import Path

def read_totals(path: Path) -> dict[str, Decimal]:
    totals: dict[str, Decimal] = defaultdict(Decimal)
    with path.open(encoding="utf-8") as source:
        for line_number, line in enumerate(source, start=1):
            category, amount = line.rstrip("\n").split(",", 1)
            try:
                totals[category.strip()] += Decimal(amount.strip())
            except InvalidOperation as error:
                raise ValueError(f"line {line_number}: invalid amount") from error
    return totals

def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("path", type=Path, help="transaction file")
    args = parser.parse_args()
    try:
        totals = read_totals(args.path)
    except (OSError, ValueError) as error:
        parser.error(str(error))
    for category in sorted(totals):
        print(f"{category},{totals[category]:.2f}")

if __name__ == "__main__":
    main()
