use std::collections::BTreeMap;
use std::env;
use std::fs;

fn main() {
    let path = env::args().nth(1).unwrap_or_else(|| {
        eprintln!("usage: totals <path>");
        std::process::exit(2);
    });
    let contents = fs::read_to_string(path).expect("unable to read transaction file");
    let mut totals: BTreeMap<String, f64> = BTreeMap::new();
    for (line_number, line) in contents.lines().enumerate() {
        let (category, amount) = line.split_once(',').unwrap_or_else(|| {
            eprintln!("line {}: row needs category and amount", line_number + 1);
            std::process::exit(2);
        });
        let value: f64 = amount.trim().parse().unwrap_or_else(|_| {
            eprintln!("line {}: invalid amount", line_number + 1);
            std::process::exit(2);
        });
        *totals.entry(category.trim().to_owned()).or_default() += value;
    }
    for (category, total) in totals {
        println!("{category},{total:.2}");
    }
}
